def binary_search(arr, target):
    low = 0
    high = len(arr) - 1

    while low <= high:
        mid = (low + high) // 2

        if arr[mid] == target:
            return mid       # Found it!
        elif target > arr[mid]:
            low = mid + 1    # Target is to the right
        else:
            high = mid - 1   # Target is to the left

    return -1                # Pointers crossed, not found

print(binary_search([1, 3, 5, 7, 9, 11, 15], 11))

def contains_target(arr, target):
    low = 0
    high = len(arr) - 1

    while low <= high:
        mid = (low + high) // 2

        if arr[mid] == target:
            return True
        elif target > arr[mid]:
            low = mid + 1
        else:
            high = mid - 1

    return False

print(contains_target([2, 4, 6, 8, 10], 6))

def recursive_binary_search(arr, target, low, high):
    # Base Case: Search space has collapsed
    if low > high:
        return -1

    mid = (low + high) // 2

    if arr[mid] == target:
        return mid

    # Conquer: Push new memory frame for the right half
    if target > arr[mid]:
        return recursive_binary_search(arr, target, mid + 1, high)

    # Conquer: Push new memory frame for the left half
    return recursive_binary_search(arr, target, low, mid - 1)

arr = [1, 3, 5, 7, 9, 11, 15]
print(recursive_binary_search(arr, 9, 0, len(arr) - 1))
